'use client';
import { Challenge } from '@/data/types';
export default function ChallengeModal({challenge,index,total,choice,setChoice,onSubmit,feedback,onClose}:{challenge:Challenge;index:number;total:number;choice:number|null;setChoice:(n:number)=>void;onSubmit:()=>void;feedback:'correct'|'wrong'|null;onClose:()=>void}) { return <div className="absolute inset-0 z-[60] flex items-center justify-center bg-black/65 p-4"><div className="panel w-full max-w-xl p-5"><div className="flex justify-between text-xs text-cyan-300"><span>CHALLENGE {index} / {total}</span><button className="retro-btn px-2" onClick={onClose}>X</button></div><h2 className="mt-3 text-lg font-black text-white">{challenge.question}</h2><div className="mt-4 grid gap-2">{challenge.options.map((option,i)=><button key={option} onClick={()=>setChoice(i)} className={`border-2 px-3 py-3 text-left text-sm ${choice===i?'border-yellow-300 bg-yellow-300/10':'border-slate-600 bg-slate-900/70'} hover:bg-slate-800`}>{String.fromCharCode(65+i)}. {option}</button>)}</div>{feedback==='wrong'&&<div className="mt-4 border border-red-500/60 bg-red-950/30 p-3 text-sm text-red-200">Not quite. Review your clues and try again.</div>}{feedback==='correct'&&<div className="mt-4 border border-green-500/60 bg-green-950/30 p-3 text-sm text-green-200">Correct! {challenge.explanation}</div>}<button disabled={choice===null||feedback==='correct'} onClick={onSubmit} className="retro-btn mt-4 w-full py-3 font-black">{feedback==='correct'?'CORRECT':'SUBMIT ANSWER'}</button></div></div>; }
